  ('8mm Pitch Acetal Hub-Mount Sprocket (14mm Bore, 40 Tooth)', '3311-0014-0040', null, 'goBILDA', null, true, 'https://www.gobilda.com/8mm-pitch-acetal-hub-mount-sprocket-14mm-bore-40-tooth/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/859/images/4694/3311-0014-0040__01828__05642.1701992271.386.513.jpg?c=1', 'MOTION / Sprockets & Chain', 'gobilda'),
  ('8mm Pitch Acetal Hub-Mount Sprocket (14mm Bore, 42 Tooth)', '3311-0014-0042', null, 'goBILDA', null, true, 'https://www.gobilda.com/8mm-pitch-acetal-hub-mount-sprocket-14mm-bore-42-tooth/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/555/images/3462/3311-0014-0042__38973__43297.1701991907.386.513.jpg?c=1', 'MOTION / Sprockets & Chain', 'gobilda'),
  ('8mm Pitch Slip-Fit Idler Sprocket (6mm Bore, 8 Tooth) - 2 Pack', '3312-0006-0008', 'This idler sprocket lets you add tension to your 8mm pitch chain in an assembly. It slips onto a 6mm OD standoff, spacer, or shaft. It also fits onto the goBILDA® Arc Slot Tensioner (1524-0001-0001) which lets you dial in the exact amount of tension you need. The built-in shims on either side of this sprocket allow it to be pressed right up against a bearing without binding the inner and outer races or needing a separate shim. The acetal makeup of this part means it will be low-friction with…', 'goBILDA', null, true, 'https://www.gobilda.com/8mm-pitch-slip-fit-idler-sprocket-6mm-bore-8-tooth-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1774/images/9401/3312-0006-0008__50229__76544.1701993773.386.513.jpg?c=1', 'MOTION / Sprockets & Chain', 'gobilda'),
  ('8mm Pitch Press-Fit Pinion Sprocket (8mm REX® Bore, 8 Tooth) - 2 Pack', '3312-4008-0008', 'This pinion sprocket lets you drive your 8mm pitch chain in an assembly. It press-fits onto an 8mm REX® shaft. The snug fit means you do not need to axially constrain the sprocket in most cases. The built-in shims on either side of this sprocket allow it to be pressed right up against a bearing without binding the inner and outer races or needing a separate shim. The acetal makeup of this part means it will be low-friction with excellent wear characteristics.', 'goBILDA', null, true, 'https://www.gobilda.com/8mm-pitch-press-fit-pinion-sprocket-8mm-rex-bore-8-tooth-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1772/images/9384/3312-4008-0008__28721__27649.1701993768.386.513.jpg?c=1', 'MOTION / Sprockets & Chain', 'gobilda'),
  ('8mm Pitch Grid-Chain (50 Pack)', '3313-0108-0050', 'Tread new ground with goBILDA® Grid-Chain! This bundle includes 50 links of Plastic Grid-Chain perfect for tank tracks, custom wheels, or even hinges. Thru-holes allow for components to fasten to any link of the track with M4 screws. The chain''s interchangeability with goBILDA® plastic chain-links allows you to create unique sequences tailored to your build!', 'goBILDA', null, true, 'https://www.gobilda.com/8mm-pitch-grid-chain-50-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1818/images/9785/3313-0108-0050__83695__53293.1701993901.386.513.jpg?c=1', 'MOTION / Sprockets & Chain / 8mm Pitch Chain', 'gobilda'),
  ('8mm Pitch Steel Chain Loop (22 Links, 176mm Pitch Length)', '3315-0008-0022', 'A continuous loop chain is helpful when you know exactly the length of chain your project needs. It also saves you the hassle of chain construction! As such, the absence of the unique "master link" you''d need to connect the ends of your chain means that every link is identical. This 8mm pitch steel chain has an impressive 120kg working load: more than triple what #25 (0.250") chain is able to handle! The 8mm pitch of the chain coincides with the 8mm grid used throughout the goBILDA® build…', 'goBILDA', null, true, 'https://www.gobilda.com/8mm-pitch-steel-chain-loop-22-links-176mm-pitch-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2189/images/12554/3315-0008-0022__13799__36604.1720040340.386.513.jpg?c=1', 'MOTION / Sprockets & Chain / 8mm Pitch Chain', 'gobilda'),
